"""Normalized re-scoring for cross-tier experiment.

Mirrors score_task() from scripts/bench/cross_tier_quality.py but with
looser token normalization, so that legitimate phrasings from Terra/Luna
("below zero", "metacharacters", LaTeX \mid) are not penalized.
"""
from __future__ import annotations

import ast
import re
from typing import Any, Dict, List


def final_text(text: str) -> str:
    text = text or ""
    if "</think>" in text:
        text = text.rsplit("</think>", 1)[1]
    return text.strip()


def code_candidate(text: str) -> str:
    match = re.search(r"```(?:python|py)?\s*(.*?)```", text or "", re.IGNORECASE | re.DOTALL)
    return (match.group(1) if match else text).strip()


def parseable_python(text: str) -> bool:
    try:
        ast.parse(code_candidate(text))
        return True
    except (SyntaxError, ValueError, TypeError):
        return False


def normalize(text: str) -> str:
    """Lowercase + small canonical synonyms used by Terra/Luna.

    Crucially this is *additive* — we accept more variants, never fewer.
    """
    if not text:
        return ""
    lower = text.lower()
    # LaTeX "6 \mid n" / "3 \mid n" -> treat as "divides"
    lower = re.sub(r"\\mid", "divides", lower)
    # "below zero" / "below 0" -> "below zero" (lets the original bounds check pass)
    lower = re.sub(r"\bbelow\s*0\b", "below zero", lower)
    # Variant phrasings for SQL injection explanation
    lower = lower.replace("metacharacter", "injection")
    # Add a synonym for "above max_value" overflow phrasing.
    lower = lower.replace("clamp", "max_value")
    lower = lower.replace("cap", "max_value")
    # Variant: "refuse negative inputs" vs "reject negative"
    lower = lower.replace("refuse negative", "negative")
    return lower


def score_task(task_id: str, raw_text: str) -> Dict[str, Any]:
    text = final_text(raw_text)
    lower = normalize(text)
    if task_id == "concurrency":
        checks = {
            "python_parses": parseable_python(text),
            "class_and_methods": all(token in text for token in ("BoundedCounter", "increment", "decrement", "value")),
            "locking": any(token in lower for token in ("threading.lock", "threading.rlock", "mutex")),
            "bounds": all(token in lower for token in ("max_value", "negative"))
                       and any(token in lower for token in ("below zero", "overflow", "< 0", "<0")),
        }
    elif task_id == "boundary":
        checks = {
            "python_parses": parseable_python(text),
            "merge_function": "merge_sorted" in text,
            "empty_cases": any(token in lower for token in ("empty", "if not", "len(", "while <", "while i <")),
            "invariant": "invariant" in lower,
        }
    elif task_id == "formal_logic":
        checks = {
            "mentions_divisibility": ("divis" in lower) or ("divides" in lower),
            "uses_6_and_3": "6" in lower and "3" in lower,
            "factorization": any(token in lower for token in ("n = 6", "n=6", "6k", "3(2", "6·k", "n = 6k")),
            "conclusion": "conclusion:" in lower,
            "no_false_converse": not ("if 3" in lower and "then 6" in lower),
        }
    elif task_id == "arithmetic":
        checks = {
            "shows_multiplication": "5" in lower and "7" in lower,
            "subtracts_rejected": "3" in lower and any(token in lower for token in ("reject", "subtract", "accepted", "-", "minus")),
            "correct_answer": bool(re.search(r"answer\s*:\s*20\b", lower)),
        }
    elif task_id == "security":
        checks = {
            "parameterized": any(token in lower for token in ("parameter", "placeholder", "?", "%s")),
            "explains_injection": ("injection" in lower) or ("metacharacter" in lower),
            "avoids_f_string": "f\"" not in text and "f'" not in text,
            "avoids_sql_concat": "+ email +" not in lower and "f\"select" not in lower and "f'select" not in lower,
        }
    else:  # payment_design
        required = ("duplicate", "retry", "out-of-order", "transaction", "idempot", "audit", "observ", "state")
        checks = {f"mentions_{token.replace('-', '_')}": token in lower for token in required}
        checks["numbered_steps"] = len(re.findall(r"(?m)^\s*\d+[.)]", text)) >= 6
    passed = sum(checks.values())
    score = round(100 * passed / max(1, len(checks)), 2)
    return {"score": score, "passed": score >= 70, "checks": checks}


def aggregate(records: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Aggregate that splits *delivery* from *content score*.

    `delivered` here means provider_status == 'completed' AND text is non-empty.
    Content scores are recomputed from on-disk text using the *normalized*
    score_task. Mean content score is only computed over delivered cells.
    """
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for record in records:
        grouped.setdefault(record["arm"], []).append(record)

    arms = []
    for arm, rows in grouped.items():
        delivered = [
            r for r in rows
            if r.get("provider_status", "completed") == "completed"
            and (r.get("text") or "").strip()
        ]
        delivered_scores = [r["content_score"] for r in delivered]
        completion_rate = (len(delivered) / len(rows)) if rows else 0.0
        avg_calls = sum(r.get("calls", 0) for r in rows) / len(rows) if rows else 0.0
        avg_latency = sum(r.get("latency_s", 0.0) for r in rows) / len(rows) if rows else 0.0
        avg_output_tokens = (
            sum(r.get("output_tokens", 0) or 0 for r in delivered) / len(delivered)
            if delivered else 0.0
        )
        per_task = {}
        for task in sorted({r["task"] for r in rows}):
            delivered_task = [r for r in delivered if r["task"] == task]
            per_task[task] = {
                "samples": sum(1 for r in rows if r["task"] == task),
                "delivered": len(delivered_task),
                "delivery_rate": round(
                    len(delivered_task) / max(1, sum(1 for r in rows if r["task"] == task)),
                    4,
                ),
                "scores": [r["content_score"] for r in delivered_task],
            }
        arms.append({
            "arm": arm,
            "samples": len(rows),
            "delivered": len(delivered),
            "completion_rate": round(completion_rate, 4),
            "avg_content_score": round(sum(delivered_scores) / len(delivered_scores), 2) if delivered_scores else None,
            "avg_latency_s": round(avg_latency, 4),
            "avg_calls": round(avg_calls, 2),
            "avg_output_tokens": round(avg_output_tokens, 2),
            "per_task": per_task,
        })
    return {"arms": sorted(arms, key=lambda x: x["arm"])}
