args.js:
const fs = require('fs');
const path = require('path');
const src = path.join('reports','jinjiang-r20','blindtest_packs');
const outRoot = path.join('reports','jinjiang-r20','isolated-reader-packs');
fs.rmSync(outRoot, { recursive: true, force: true });
fs.mkdirSync(outRoot, { recursive: true });
for (let i = 1; i <= 5; i++) {
  const d = path.join(outRoot, `persona-${i}`);
  fs.mkdirSync(d, { recursive: true });
  for (const f of fs.readdirSync(src)) {
    if (!f.endsWith('.md')) continue;
    fs.copyFileSync(path.join(src, f), path.join(d, f));
  }
}
function walk(dir) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...walk(p));
    else out.push({ p, len: fs.statSync(p).size });
  }
  return out;
}
console.log(JSON.stringify(walk(outRoot), null, 2));

