)
foreach ($n in $candidates) {
  $repo = "stancsz/$n"
  $r = gh repo view $repo --json nameWithOwner 2>&1 | Out-String
  if ($LASTEXITCODE -eq 0) { "{0,-22} YOUR_REPO_TAKEN" -f $n; continue }
  $enc = [uri]::EscapeDataString("$n in:name")
  $sr = gh api "search/repositories?q=$enc&per_page=5" 2>&1 | Out-String | ConvertFrom-Json -ErrorAction SilentlyContinue
  $exact = @($sr.items | Where-Object { $_.name -ieq $n })
  if ($exact.Count -gt 0) {
    "{0,-22} GLOBAL_EXACT_TAKEN  {1}" -f $n, (($exact | ForEach-Object { $_.full_name }) -join ', ')
  } else {
    "{0,-22} OK  similar={1}" -f $n, $sr.total_count
  }
}

