python3 -c "
src = open('engine/prose_lint.py', encoding='utf-8').read()
old = '''def load_stub_set():
    \"\"\"读 _STUB_MANIFEST.json，返回 stub 文件名集合。文件不存在则返回空集。\"\"\"
    if not os.path.isfile(STUB_MANIFEST):
        return set()
    try:
        with open(STUB_MANIFEST, encoding=\"utf-8\") as fh:
            data = json.load(fh)
        return {entry[\"filename\"] for entry in data.get(\"files\", [])}
    except Exception:
        return set()'''
new = '''def load_stub_set():
    \"\"\"读 _STUB_MANIFEST.json，返回 stub 文件名集合。文件不存在则返回空集。

    兼容两种 files 格式：
      - files: [{\"filename\": \"...\"}, ...]   （旧 dict 列表）
      - files: [\"...\", ...]                  （新字符串列表，P0 落地后采用）
    \"\"\"
    if not os.path.isfile(STUB_MANIFEST):
        return set()
    try:
        with open(STUB_MANIFEST, encoding=\"utf-8\") as fh:
            data = json.load(fh)
        out = set()
        for entry in data.get(\"files\", []):
            if isinstance(entry, dict):
                fn = entry.get(\"filename\", \"\")
                if fn:
                    out.add(fn)
            elif isinstance(entry, str):
                if entry:
                    out.add(entry)
        return {x for x in out if x}
    except Exception:
        return set()'''
if old in src:
    new_src = src.replace(old, new)
    open('engine/prose_lint.py', 'w', encoding='utf-8').write(new_src)
    print('replaced')
else:
    print('not found')
"

