import json, pathlib
data = json.loads(pathlib.Path('reports/jinjiang-r20/chapter-distance.json').read_text(encoding='utf-8'))
targets = {1,2,3,5,8,17,20,24,27}
buckets = {}
for row in data['records']:
    eng = row['engineering']
    label = eng['E6_hook_label']
    buckets.setdefault(label, []).append(row['engineering_min'])
print('hook_label distribution:')
for k,v in sorted(buckets.items(), key=lambda kv:-len(kv[1])):
    print(f'  {k:>14}  count={len(v):>5}  mean={sum(v)/len(v):.2f}')
print()
print('entry chapters:')
for row in data['records']:
    if row['chapter'] in targets:
        e = row['engineering']
        print(f"  ch{row['chapter']:>4}  E_min={row['engineering_min']}  E1={e['E1_open_conflict']}  E2={e['E2_mid_turn']}  E3={e['E3_hook_stop']}  E4={e['E4_agency']}  E5={e['E5_relationship_cost']}  E5_pov={e['E5_pov_initiator']}  E6={e['E6_hook_type']}({e['E6_hook_label']})")
